dashboard.definition:
{
  "title": "SC4S Syslog & Edge/Ingest Processors",
  "description": "Syslog/SC4S source volume plus Edge Processor in-flight vs indexed volume and filter efficiency.",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-4h@h,now"
      }
    }
  },
  "dataSources": {
    "ds_sc4s_time": {
      "type": "ds.search",
      "name": "SC4S / syslog over time",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` `exec_health_sc4s` by _time span=5m sourcetype\n| timechart span=5m sum(events) as events by sourcetype",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_sc4s_hosts": {
      "type": "ds.search",
      "name": "Events per syslog source",
      "options": {
        "query": "| tstats count as events where index=`exec_health_idx` `exec_health_sc4s` by host sourcetype\n| sort 0 -events\n| head 50\n| eval _color_rank=3",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_sc4s_errors": {
      "type": "ds.search",
      "name": "SC4S container issues",
      "options": {
        "query": "search index=`exec_health_sc4s_idx` `exec_health_sc4s` (error OR warn OR fail OR \"connection refused\" OR hang OR dropped)\n| stats count as issues by host, sourcetype\n| eval _color_rank=if(issues>0, 1, 3)\n| sort 0 -issues",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_sc4s_err_time": {
      "type": "ds.search",
      "name": "SC4S issues over time",
      "options": {
        "query": "search index=`exec_health_sc4s_idx` `exec_health_sc4s` (error OR warn OR fail OR \"connection refused\")\n| timechart span=5m count as sc4s_issues",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_edge_summary": {
      "type": "ds.search",
      "name": "Edge Processor summary",
      "options": {
        "query": "| mstats rate_sum(processor_events_in_total) as events_in_eps, rate_sum(processor_events_out_total) as events_out_eps, rate_sum(processor_bytes_in_total) as bytes_in_eps, rate_sum(processor_bytes_out_total) as bytes_out_eps where `exec_health_edge_mstats`\n| appendpipe [ stats count | where count=0 | eval events_in_eps=0, events_out_eps=0, bytes_in_eps=0, bytes_out_eps=0 ]\n| fillnull value=0 events_in_eps, events_out_eps, bytes_in_eps, bytes_out_eps\n| eval filter_efficiency_pct=if(events_in_eps>0, round(((events_in_eps-events_out_eps)/events_in_eps)*100, 2), 0)\n| eval events_in_eps=round(events_in_eps, 2), events_out_eps=round(events_out_eps, 2)\n| eval bytes_in_mbps=round(bytes_in_eps/1024/1024, 3)",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_edge_tp": {
      "type": "ds.search",
      "name": "Edge throughput by host",
      "options": {
        "query": "| mstats rate_sum(processor_events_in_total) as events_in_eps, rate_sum(processor_events_out_total) as events_out_eps, rate_sum(processor_bytes_in_total) as bytes_in_eps, rate_sum(processor_bytes_out_total) as bytes_out_eps where `exec_health_edge_mstats` by host span=5m\n| eval filter_efficiency_pct=if(events_in_eps>0, round(((events_in_eps-events_out_eps)/events_in_eps)*100, 2), 0)\n| eval dropped_or_filtered_eps=round(events_in_eps-events_out_eps, 2)\n| eval events_in_eps=round(events_in_eps, 2), events_out_eps=round(events_out_eps, 2)\n| eval _color_rank=case(events_in_eps>0 AND events_out_eps=0, 1, filter_efficiency_pct>50, 2, 1=1, 3)",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_edge_queue": {
      "type": "ds.search",
      "name": "Edge queues and export errors",
      "options": {
        "query": "| mstats max(queue_size_bytes) as queue_size_bytes, max(queue_max_bytes) as queue_max_bytes, rate_sum(export_destination_errors_total) as export_errors_per_sec where `exec_health_edge_mstats` by host\n| eval queue_mb=round(queue_size_bytes/1024/1024, 2)\n| eval queue_fill_pct=if(queue_max_bytes>0, round(queue_size_bytes/queue_max_bytes*100, 1), null())\n| eval export_errors_per_sec=round(coalesce(export_errors_per_sec, 0), 3)\n| eval _color_rank=case(export_errors_per_sec>0 OR queue_fill_pct>=80, 1, queue_fill_pct>=50, 2, 1=1, 3)\n| table host, queue_mb, queue_fill_pct, export_errors_per_sec, _color_rank",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_edge_logs": {
      "type": "ds.search",
      "name": "Edge / ingest processor logs",
      "options": {
        "query": "search index=_internal (source=\"*edge.log\" OR sourcetype=edge OR sourcetype=*edge*processor* OR component=IngestActions OR component=IngestProcessor)\n| eval is_drop=if(match(_raw, \"(?i)drop|filter|sending_queue is full\"), 1, 0)\n| stats count as events, sum(is_drop) as drop_mentions by sourcetype, host\n| eval _color_rank=if(drop_mentions>0, 1, 3)\n| sort 0 -drop_mentions, -events",
        "refresh": "5m",
        "refreshType": "delay"
      }
    },
    "ds_indexed": {
      "type": "ds.search",
      "name": "Indexed events reaching indexers",
      "options": {
        "query": "| tstats count as indexed_events where index=`exec_health_idx` by _time span=5m\n| timechart span=5m sum(indexed_events) as indexed_events",
        "refresh": "5m",
        "refreshType": "delay"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# SC4S and Edge / Ingest Processors\nLeft side watches **syslog/SC4S** volume per source host (load-balancer hang = flatline). Right side compares **Edge Processor in vs out** (`mstats rate_sum` on `_metrics`) with **events reaching indexers**.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_ep_in": {
      "type": "splunk.singlevalue",
      "title": "Edge events in / sec",
      "dataSources": {
        "primary": "ds_edge_summary"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"events_in_eps\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 2,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_ep_out": {
      "type": "splunk.singlevalue",
      "title": "Edge events out / sec",
      "dataSources": {
        "primary": "ds_edge_summary"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"events_out_eps\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 2,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_filter": {
      "type": "splunk.singlevalue",
      "title": "Filter efficiency",
      "dataSources": {
        "primary": "ds_edge_summary"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"filter_efficiency_pct\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 1,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "unit": " %",
        "unitPosition": "after",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_mbps": {
      "type": "splunk.singlevalue",
      "title": "Edge bytes in",
      "dataSources": {
        "primary": "ds_edge_summary"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"bytes_in_mbps\") | lastPoint()",
        "backgroundColor": "transparent",
        "shouldUseThousandSeparators": true,
        "numberPrecision": 3,
        "majorFontSize": 32,
        "majorColor": "#58A6FF",
        "unit": " MB/s",
        "unitPosition": "after",
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_sc4s_time": {
      "type": "splunk.area",
      "title": "SC4S / syslog events by sourcetype",
      "dataSources": {
        "primary": "ds_sc4s_time"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "seriesColors": [
          "#58A6FF",
          "#3FB950",
          "#E3B341",
          "#F85149",
          "#A371F7"
        ],
        "legendDisplay": "right",
        "yAxisTitleText": "events / 5m",
        "areaOpacity": 0.35,
        "nullValueDisplay": "connect",
        "backgroundColor": "transparent"
      }
    },
    "viz_indexed": {
      "type": "splunk.line",
      "title": "Events reaching indexers (tstats)",
      "dataSources": {
        "primary": "ds_indexed"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "seriesColors": [
          "#58A6FF",
          "#3FB950",
          "#E3B341",
          "#F85149",
          "#A371F7"
        ],
        "legendDisplay": "right",
        "yAxisTitleText": "indexed events / 5m",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "markerDisplay": "off",
        "backgroundColor": "transparent"
      }
    },
    "viz_sc4s_hosts": {
      "type": "splunk.table",
      "title": "Events per source (host)",
      "dataSources": {
        "primary": "ds_sc4s_hosts"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "count": 20,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)",
          "headerBackgroundColor": "transparent",
          "headerColor": "#8B949E"
        },
        "columnFormat": {
          "severity": {
            "rowColors": "> table | seriesByName(\"severity\") | matchValue(pillText)",
            "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(pillBg)"
          },
          "status": {
